(186, 'landing_page_config', '{\"site_name\":\"AI Screenplay\",\"sections_visible\":{\"hero\":true,\"features\":true,\"workflow\":true,\"tools\":true,\"testimonials\":true,\"cta\":true},\"hero\":{\"badge\":\"Powered by AI\",\"title_before\":\"Biến Ý Tưởng Thành\",\"title_gradient\":\"Kịch Bản Phim\",\"title_after\":\"Chuyên Nghiệp\",\"subtitle\":\"Công cụ AI hỗ trợ viết kịch bản phim theo quy trình Hollywood chuẩn. Từ ý tưởng đến kịch bản hoàn chỉnh chỉ trong vài bước đơn giản.\",\"cta_primary\":\"Bắt đầu sáng tạo\",\"cta_secondary\":\"Xem cách hoạt động\",\"stat_0_count\":9,\"stat_0_label\":\"Công cụ AI\",\"stat_1_count\":1000,\"stat_1_label\":\"Kịch bản đã tạo\",\"stat_2_count\":500,\"stat_2_label\":\"Người dùng\"},\"features\":{\"badge\":\"Tính năng\",\"title\":\"Tại sao chọn AI Screenplay?\",\"subtitle\":\"Công cụ mạnh mẽ giúp bạn viết kịch bản nhanh hơn và chuyên nghiệp hơn\",\"cards\":[{\"icon\":\"fa-brain\",\"title\":\"AI Thông Minh\",\"desc\":\"Sử dụng mô hình ngôn ngữ tiên tiến để tạo nội dung sáng tạo và phù hợp với ngữ cảnh\"},{\"icon\":\"fa-route\",\"title\":\"Quy Trình Chuẩn\",\"desc\":\"Theo quy trình viết kịch bản Hollywood với 9 bước từ Logline đến Kịch bản hoàn chỉnh\"},{\"icon\":\"fa-clock\",\"title\":\"Tiết Kiệm Thời Gian\",\"desc\":\"Giảm thời gian viết kịch bản từ vài tháng xuống còn vài ngày với sự hỗ trợ của AI\"},{\"icon\":\"fa-edit\",\"title\":\"Chỉnh Sửa Linh Hoạt\",\"desc\":\"Dễ dàng chỉnh sửa và điều chỉnh nội dung theo ý muốn với giao diện trực quan\"},{\"icon\":\"fa-database\",\"title\":\"Lưu Trữ An Toàn\",\"desc\":\"Tất cả dự án được lưu trữ an toàn trên cloud, truy cập mọi lúc mọi nơi\"},{\"icon\":\"fa-language\",\"title\":\"Hỗ Trợ Tiếng Việt\",\"desc\":\"Giao diện và nội dung hoàn toàn bằng tiếng Việt, phù hợp với nhà biên kịch Việt Nam\"}]},\"testimonials\":{\"badge\":\"Đánh giá\",\"title\":\"Người Dùng Nói Gì?\",\"subtitle\":\"Phản hồi từ các nhà biên kịch đã sử dụng AI Screenplay\",\"items\":[{\"text\":\"AI Screenplay đã giúp tôi tiết kiệm rất nhiều thời gian trong quá trình phát triển ý tưởng. Từ một ý tưởng mơ hồ, tôi đã có được kịch bản hoàn chỉnh trong 2 tuần!\",\"author\":\"Nguyễn Văn A\",\"role\":\"Biên kịch phim truyền hình\"},{\"text\":\"Công cụ tuyệt vời cho cả người mới và chuyên nghiệp. Quy trình 8  bước rất logic và giúp tôi không bỏ sót bất kỳ yếu tố quan trọng nào trong kịch bản.\",\"author\":\"Trần Thị B\",\"role\":\"Đạo diễn phim ngắn\"},{\"text\":\"Sinh viên điện ảnh như tôi rất cần một công cụ hỗ trợ như thế này. AI Screenplay không viết thay mình mà hướng dẫn mình viết đúng cách.\",\"author\":\"Lê Văn C\",\"role\":\"Sinh viên Điện ảnh\"}]},\"workflow\":{\"badge\":\"Quy trình\",\"title\":\"8 Bước Tạo Kịch Bản Hoàn Hảo\",\"subtitle\":\"Quy trình viết kịch bản chuyên nghiệp theo chuẩn Hollywood\",\"steps\":[{\"icon\":\"fa-pen-fancy\",\"title\":\"Tạo Logline\",\"desc\":\"Tóm tắt phim trong 1-2 câu, nêu bật nhân vật, mục tiêu và xung đột\"},{\"icon\":\"fa-lightbulb\",\"title\":\"Xác Định Chủ Đề\",\"desc\":\"Tìm ra thông điệp sâu sắc và ý nghĩa của câu chuyện\"},{\"icon\":\"fas fa-users\",\"title\":\"Mô Tả Nhân Vật\",\"desc\":\"Xây dựng hồ sơ chi tiết cho từng nhân vật trong phim\"},{\"icon\":\"fas fa-file-alt\",\"title\":\"Viết Synopsis\",\"desc\":\"Tóm tắt toàn bộ câu chuyện từ đầu đến cuối\"},{\"icon\":\"fas fa-sitemap\",\"title\":\"Cấu Trúc 4 Hồi\",\"desc\":\"Phân chia câu chuyện theo cấu trúc Story Circle\"},{\"icon\":\"fas fa-chart-line\",\"title\":\"Tạo Beat Sheet\",\"desc\":\"Liệt kê các beat quan trọng theo mô hình Save the Cat\"},{\"icon\":\"fas fa-th-list\",\"title\":\"Danh Sách Cảnh\",\"desc\":\"Chia kịch bản thành 30-40 cảnh rõ ràng\"},{\"icon\":\"fas fa-scroll\",\"title\":\"Viết Kịch Bản2222\",\"desc\":\"Viết kịch bản chi tiết theo format Hollywood chuẩn\"}]},\"cta\":{\"heading\":\"Sẵn Sàng Viết Kịch Bản?\",\"subtext\":\"Bắt đầu hành trình sáng tạo của bạn ngay hôm nay với AI Screenplay\"},\"footer\":{\"brand_desc\":\"Công cụ viết kịch bản phim với AI - Biến ý tưởng thành câu chuyện.\",\"copyright\":\"© 2026 AI Screenplay. Tất cả quyền được bảo lưu.\"}}', '2026-05-29 13:07:46'),
